# Let's check if any feature is a "backdoor detector" - high weight for one class, near-zero for others
# Compute max weight per feature across classes
max_weight_per_feature = fc_w.abs().max(dim=0).values
argmax_class_per_feature = fc_w.abs().argmax(dim=0)

print("Features with max weight > 0.5:")
for i in range(64):
    if max_weight_per_feature[i] > 0.5:
        print(f"  Feature {i}: max_weight={max_weight_per_feature[i]:.3f}, class={argmax_class_per_feature[i].item()}")

# Also check if any feature has weight >> 0 for one class and ~0 for others
print("\nFeature specificity (ratio of max to 2nd max):")
for i in range(64):
    sorted_w = torch.sort(fc_w[:, i].abs(), descending=True).values
    if sorted_w[0] > 0.4:
        ratio = sorted_w[0] / (sorted_w[1] + 1e-8)
        if ratio > 2.0:
            print(f"  Feature {i}: max={sorted_w[0]:.3f}, 2nd={sorted_w[1]:.3f}, ratio={ratio:.2f}, class={argmax_class_per_feature[i].item()}")
